using System.IO;
using System.Text.Json;
using Toolbox.App;

int passed=0,failed=0;
string root=Path.Combine(Path.GetTempPath(),"cz-cache-tests-"+Guid.NewGuid());Directory.CreateDirectory(root);
async Task Test(string name,Func<Task> test){try{await test();passed++;Console.WriteLine("PASS "+name);}catch(Exception ex){failed++;Console.WriteLine("FAIL "+name+": "+ex.Message);}}
void Assert(bool value,string reason){if(!value)throw new Exception(reason);}
SystemInfoReport Report(string value="CPU")=>new(){CollectedAt=DateTimeOffset.UtcNow,Sections=[new(){Id="cpu",Title="处理器",Devices=[new(){Id="cpu0",Name=value}]}]};
SystemInfoCache Cache(string file,string? boot="boot-A")=>new(Path.Combine(root,file),()=>Task.FromResult(boot));

await Test("navigation and relogin reuse an already collected snapshot",async()=>{int reads=0;var cache=Cache("same.json");Task<SystemInfoReport> Read(CancellationToken t){reads++;return Task.FromResult(Report());}await cache.GetAsync(Read,false,default);await cache.GetAsync(Read,false,default);Assert(reads==1,"automatic query repeated");});
await Test("closing and reopening in the same boot uses persisted snapshot",async()=>{string path="reopen.json";await Cache(path).GetAsync(_=>Task.FromResult(Report("persisted")),false,default);int reads=0;var report=await Cache(path).GetAsync(_=>{reads++;return Task.FromResult(Report("new"));},false,default);Assert(reads==0&&report.Sections[0].Devices[0].Name=="persisted","disk cache not reused");});
await Test("restart or hybrid-boot identity change invalidates persisted snapshot",async()=>{await Cache("restart.json").GetAsync(_=>Task.FromResult(Report("old")),false,default);int reads=0;await Cache("restart.json","boot-B").GetAsync(_=>{reads++;return Task.FromResult(Report());},false,default);Assert(reads==1,"previous boot reused");});
await Test("manual refresh updates memory and persisted data",async()=>{int reads=0;var cache=Cache("refresh.json");Task<SystemInfoReport> Read(CancellationToken t)=>Task.FromResult(Report((++reads).ToString()));await cache.GetAsync(Read,false,default);await cache.GetAsync(Read,true,default);var result=await Cache("refresh.json").GetAsync(Read,false,default);Assert(reads==2&&result.Sections[0].Devices[0].Name=="2","refresh not saved");});
await Test("simultaneous initial requests share a single collection",async()=>{var cache=Cache("parallel.json");int reads=0;async Task<SystemInfoReport> Read(CancellationToken t){Interlocked.Increment(ref reads);await Task.Delay(60,t);return Report();}await Task.WhenAll(Enumerable.Range(0,6).Select(_=>cache.GetAsync(Read,false,default)));Assert(reads==1,"parallel queries repeated");});
await Test("independent cache instances coalesce through the shared file",async()=>{var first=Cache("instances.json");var second=Cache("instances.json");int reads=0;async Task<SystemInfoReport> Read(CancellationToken t){Interlocked.Increment(ref reads);await Task.Delay(100,t);return Report();}await Task.WhenAll(first.GetAsync(Read,false,default),second.GetAsync(Read,false,default));Assert(reads==1,"independent toolboxes collected twice");});
await Test("simultaneous refreshes coalesce while collecting",async()=>{var cache=Cache("parallel-refresh.json");int reads=0;async Task<SystemInfoReport> Read(CancellationToken t){Interlocked.Increment(ref reads);await Task.Delay(60,t);return Report();}await cache.GetAsync(Read,false,default);await Task.WhenAll(Enumerable.Range(0,6).Select(_=>cache.GetAsync(Read,true,default)));Assert(reads==2,"parallel refresh repeated");});
await Test("failure never poisons previous good snapshot and retry works",async()=>{var cache=Cache("failure.json");await cache.GetAsync(_=>Task.FromResult(Report("good")),false,default);try{await cache.GetAsync(_=>throw new IOException("offline"),true,default);}catch(IOException){}var old=await cache.GetAsync(_=>throw new Exception("should use prior cache"),false,default);Assert(old.Sections[0].Devices[0].Name=="good","old snapshot lost");await cache.GetAsync(_=>Task.FromResult(Report("retry")),true,default);});
await Test("cancelled query cannot publish its result",async()=>{var cache=Cache("cancel.json");using var cts=new CancellationTokenSource();try{await cache.GetAsync(_=>{cts.Cancel();return Task.FromResult(Report());},false,cts.Token);}catch(OperationCanceledException){}Assert(!File.Exists(Path.Combine(root,"cancel.json")),"cancelled snapshot saved");int reads=0;await cache.GetAsync(_=>{reads++;return Task.FromResult(Report());},false,default);Assert(reads==1,"cancelled snapshot cached in memory");});
await Test("corrupt, wrong schema and malformed nested arrays get recollected",async()=>{foreach(string content in new[]{"broken","null","{\"Schema\":999}","{\"Schema\":1,\"BootSession\":\"boot-A\",\"Report\":{\"CollectedAt\":\"2026-10-22T01:00:00Z\",\"Sections\":[{\"Id\":\"cpu\",\"Devices\":[{\"Fields\":null}]}]}}"}){File.WriteAllText(Path.Combine(root,"corrupt.json"),content);int reads=0;await Cache("corrupt.json").GetAsync(_=>{reads++;return Task.FromResult(Report());},false,default);Assert(reads==1,"invalid cache trusted");}});
await Test("unknown boot identity keeps memory reuse but refuses cross-process cache",async()=>{int reads=0;Task<SystemInfoReport> Read(CancellationToken t){reads++;return Task.FromResult(Report());}var first=Cache("unknown.json",null);await first.GetAsync(Read,false,default);await first.GetAsync(Read,false,default);await Cache("unknown.json",null).GetAsync(Read,false,default);Assert(reads==2&&!File.Exists(Path.Combine(root,"unknown.json")),"unknown boot persisted or memory not reused");});
await Test("read-only cache location does not break hardware report",async()=>{string blocked=Path.Combine(root,"blocked");File.WriteAllText(blocked,"file");var cache=new SystemInfoCache(Path.Combine(blocked,"cache.json"),()=>Task.FromResult<string?>("boot-A"));var result=await cache.GetAsync(_=>Task.FromResult(Report()),false,default);Assert(result.Sections.Length==1,"cache IO blocked report");});
await Test("boot identity remains stable across independent readers on real Windows",async()=>{string? first=await WindowsBootSession.ReadAsync();string? second=await WindowsBootSession.ReadAsync();Assert(first!=null&&first==second,"boot identity unavailable or unstable: first="+first+" second="+second);Console.WriteLine("Boot identity: "+first);});

Directory.Delete(root,true);Console.WriteLine($"RESULT {passed} passed, {failed} failed");return failed==0?0:1;
